-- Texas Exam Prep — Phase 2 schema
--
-- Generated by scripts/build-deploy-sql.mjs. Do not edit by hand; edit the
-- migrations in supabase/migrations/ and regenerate.
--
-- Run this ONCE against a project that already has the Phase 1 schema.
-- These statements are not idempotent: running them twice fails on an
-- existing type or table, which is the correct behaviour, not a bug.
--
-- Wrapped in a single transaction, so a failure anywhere leaves the
-- database exactly as it was rather than half-migrated.
--   - 20260201000000_content_types.sql
--   - 20260201000100_modules.sql
--   - 20260201000200_lessons.sql
--   - 20260201000300_topics.sql
--   - 20260201000400_content_grants.sql
--   - 20260201000500_content_rls.sql
--   - 20260201000600_lesson_completions.sql
--   - 20260201000700_topic_question_count.sql

begin;

-- --------------------------------------------------------------------------
-- 20260201000000_content_types.sql
-- --------------------------------------------------------------------------

-- ===========================================================================
-- Phase 2 / 01 — Content enum types.
--
-- Mirrors the Phase 1 rationale for native enums over constrained text: one
-- authoritative definition, type safety inside policies and functions, and
-- automatic exposure to the generated TypeScript types.
-- ===========================================================================

-- Deliberately a SEPARATE type from public.course_status, even though the two
-- currently carry identical values.
--
-- A course's lifecycle and a lesson's lifecycle are different things that
-- happen to rhyme today. Sharing one type would mean that the first time
-- either side needs a value the other must not have -- a course that is
-- 'coming_soon', a lesson that is 'needs_review' -- every policy and every
-- switch statement on the other side silently gains a case it does not
-- handle. Two small types cost one extra declaration; one shared type costs a
-- migration that cannot be made safely.
create type public.content_status as enum ('draft', 'active', 'archived');

comment on type public.content_status is
  'Publication state for modules, lessons and (Phase 2 later) questions. '
  'Only active rows are visible to non-admins.';

-- --------------------------------------------------------------------------
-- 20260201000100_modules.sql
-- --------------------------------------------------------------------------

-- ===========================================================================
-- Phase 2 / 02 — modules
--
-- A module is an ordered chapter within a course. It is a TEACHING structure:
-- how the material is sequenced. It is deliberately not the same thing as a
-- topic, which is how the state EXAMINES the material. See
-- docs/phase-2-design.md, section 3.
-- ===========================================================================

create table public.modules (
  id          uuid primary key default gen_random_uuid(),
  course_id   uuid not null references public.courses (id) on delete cascade,
  title       text not null,
  description text,
  position    integer not null,
  status      public.content_status not null default 'draft',
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),

  constraint modules_title_length check (char_length(title) between 1 and 200),
  constraint modules_position_positive check (position > 0),

  -- Ordering within a course is unique, but DEFERRABLE.
  --
  -- Reordering modules means rewriting several rows' positions, and any
  -- sequence of individual UPDATEs passes through a state where two rows
  -- briefly share a position. With an immediate constraint the only ways out
  -- are a temporary sentinel position (ugly, and leaves debris if the
  -- transaction dies) or renumbering in an order the caller has to compute.
  -- Deferring the check to COMMIT lets a reorder be written as the obvious
  -- set of UPDATEs inside one transaction:
  --
  --   begin;
  --   set constraints public.modules_course_position_key deferred;
  --   update public.modules set position = 2 where id = '...';
  --   update public.modules set position = 1 where id = '...';
  --   commit;
  --
  -- INITIALLY IMMEDIATE keeps the default strict, so an ordinary single-row
  -- insert still fails fast at the statement rather than at COMMIT.
  --
  -- THE COST, so it is not rediscovered the hard way: PostgreSQL refuses a
  -- DEFERRABLE constraint as an ON CONFLICT arbiter. `on conflict
  -- (course_id, position)` is therefore an error, and an upsert on this table
  -- must arbitrate on the primary key instead. supabase/seed.sql does exactly
  -- that, for exactly this reason.
  constraint modules_course_position_key unique (course_id, position)
    deferrable initially immediate,

  -- Not redundant with the primary key, despite appearances. This is the
  -- target of the composite foreign key on public.lessons, which is what
  -- makes lessons.course_id provably consistent with its module's course
  -- without a trigger. See the note in the lessons migration.
  constraint modules_id_course_key unique (id, course_id)
);

comment on table public.modules is
  'Ordered chapters within a course. Only status = active modules of an '
  'active course are readable by non-admins.';

comment on column public.modules.position is
  'One-based ordering within the course. Unique per course, deferrable so a '
  'multi-row reorder can be done in a single transaction.';

-- The catalogue and syllabus pages read every module of one course in order.
create index modules_course_position_idx
  on public.modules (course_id, position);

create trigger modules_set_updated_at
  before update on public.modules
  for each row execute function public.set_updated_at();

-- --------------------------------------------------------------------------
-- 20260201000200_lessons.sql
-- --------------------------------------------------------------------------

-- ===========================================================================
-- Phase 2 / 03 — lessons and lesson_contents
--
-- THE SPLIT, AND WHY IT EXISTS
--
-- A lesson has two halves with genuinely different audiences:
--
--   * Its METADATA -- title, slug, position, estimated_minutes -- is the
--     public syllabus. It is what a prospective student reads before paying,
--     and what a search engine indexes. It must be visible to anonymous
--     visitors.
--
--   * Its BODY is the product. It must be visible only to a student with a
--     live enrollment in the course.
--
-- Those two rules cannot both be applied to one row. RLS decides which ROWS a
-- caller sees; column-level GRANTs decide which COLUMNS a ROLE may touch.
-- Neither can express "this role may read these columns of this row but not
-- those columns of the same row" -- an anonymous visitor and an enrolled
-- student both connect as a database role (anon / authenticated), and the
-- enrolled student's privilege is a property of their enrollment row, not of
-- their role. A single `lessons.body` column therefore has no correct grant:
-- granting it hands the course to anonymous visitors, revoking it hides the
-- course from the students who paid for it.
--
-- So the body lives in its own table, public.lesson_contents, with its own
-- policy. This is the same reasoning that puts the answer key in
-- question_answers rather than in a column of question_options
-- (docs/phase-2-design.md, section 1): when a thing is secret, making it a
-- separate table means the grant surface is a whole table that nobody widens
-- by accident, rather than a column somebody has to remember to exclude from
-- `select=*`.
-- ===========================================================================

create table public.lessons (
  id         uuid not null default gen_random_uuid(),
  module_id  uuid not null,

  -- Denormalised from modules.course_id, and PROVABLY consistent with it.
  --
  -- The composite foreign key below points at modules (id, course_id), so
  -- PostgreSQL itself refuses any row whose course_id disagrees with its
  -- module's. `on update cascade` means moving a module to another course
  -- rewrites its lessons' course_id in the same statement rather than
  -- breaking the reference.
  --
  -- This is worth one redundant column. Without it, every enrollment check in
  -- an RLS policy -- "may this caller read this lesson's body?" -- has to join
  -- lessons to modules to reach a course id, on every row, inside a policy
  -- that is evaluated for every row scanned. With it, the policy reads one
  -- column. The usual objection to denormalisation is that the copy drifts
  -- from the original; a composite foreign key is exactly the mechanism that
  -- makes drift impossible, so the objection does not apply here.
  course_id  uuid not null,

  title      text not null,
  slug       text not null,
  summary    text,
  position   integer not null,
  status     public.content_status not null default 'draft',
  estimated_minutes integer,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),

  constraint lessons_pkey primary key (id),

  constraint lessons_module_fkey
    foreign key (module_id, course_id)
    references public.modules (id, course_id)
    on update cascade
    on delete cascade,

  constraint lessons_title_length check (char_length(title) between 1 and 200),
  constraint lessons_slug_format check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  constraint lessons_slug_length check (char_length(slug) between 1 and 120),
  constraint lessons_position_positive check (position > 0),
  constraint lessons_estimated_minutes_sane
    check (estimated_minutes is null or estimated_minutes between 1 and 600),

  -- Readable URLs: /courses/:courseSlug/:moduleSlug-ish/:lessonSlug. Unique
  -- per module rather than per course, so "introduction" can appear once in
  -- each module without the author inventing disambiguating names.
  constraint lessons_module_slug_key unique (module_id, slug),

  -- Deferrable for the same reordering reason as modules.position.
  constraint lessons_module_position_key unique (module_id, position)
    deferrable initially immediate,

  -- FK target for lesson_contents and lesson_topics, both of which carry
  -- course_id for the same policy-performance reason as above.
  constraint lessons_id_course_key unique (id, course_id)
);

comment on table public.lessons is
  'Lesson METADATA only -- the public syllabus. The body lives in '
  'public.lesson_contents, which is readable only by enrolled students.';

comment on column public.lessons.course_id is
  'Denormalised from modules.course_id and held consistent by the composite '
  'foreign key lessons_module_fkey. Do not set it independently.';

comment on column public.lessons.summary is
  'One or two sentences shown in the syllabus. PUBLIC -- never put exam '
  'content or answers here.';

create index lessons_module_position_idx
  on public.lessons (module_id, position);

create index lessons_course_id_idx on public.lessons (course_id);

create trigger lessons_set_updated_at
  before update on public.lessons
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- lesson_contents — the paid half.
-- ---------------------------------------------------------------------------
create table public.lesson_contents (
  lesson_id  uuid not null,

  -- Same denormalisation, same composite-FK guarantee, same reason: the
  -- enrollment check in this table's RLS policy is the hottest policy in the
  -- application and should not have to join two tables to find a course id.
  course_id  uuid not null,

  body       text not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),

  constraint lesson_contents_pkey primary key (lesson_id),

  constraint lesson_contents_lesson_fkey
    foreign key (lesson_id, course_id)
    references public.lessons (id, course_id)
    on update cascade
    on delete cascade
);

comment on table public.lesson_contents is
  'Lesson bodies. Markdown (decision A, docs/phase-2-design.md). Readable '
  'only by an admin or a student with a live enrollment in course_id. No '
  'grants at all to anon.';

comment on column public.lesson_contents.body is
  'Markdown. Rendered server-side through a sanitising pipeline -- raw HTML '
  'is not honoured, because an instructor account is not a reason to allow '
  'arbitrary markup into another user''s browser.';

create index lesson_contents_course_id_idx on public.lesson_contents (course_id);

create trigger lesson_contents_set_updated_at
  before update on public.lesson_contents
  for each row execute function public.set_updated_at();

-- --------------------------------------------------------------------------
-- 20260201000300_topics.sql
-- --------------------------------------------------------------------------

-- ===========================================================================
-- Phase 2 / 04 — topics and lesson_topics
--
-- A topic is a node of the STATE'S exam blueprint, not of our course outline.
-- Modules are how we teach; topics are how the exam tests. Keeping them as
-- separate hierarchies is what makes "you are weak on Texas statutes" an
-- answerable question later -- if topics were just modules under another
-- name, a readiness score could only ever say "you are weak on chapter 4",
-- which is a fact about our book rather than about the exam.
-- ===========================================================================

create table public.topics (
  id              uuid primary key default gen_random_uuid(),
  course_id       uuid not null references public.courses (id) on delete cascade,

  -- Nullable self-reference. Deleting a parent that still has children is
  -- REJECTED rather than cascaded: a topic subtree is the spine of every
  -- historical score that references it, and losing one to a mis-clicked
  -- delete should require the author to say so explicitly, child by child.
  parent_topic_id uuid references public.topics (id) on delete restrict,

  -- The blueprint's own identifier, e.g. 'P&C.03.02'. Free-form text rather
  -- than a parsed structure: it comes from a published state document and its
  -- format is not ours to constrain.
  code            text not null,
  name            text not null,

  -- The published percentage weighting for this topic, where the blueprint
  -- gives one. Used later to weight a readiness score so that a 15%-of-the-
  -- exam topic counts for more than a 2% one.
  blueprint_weight numeric(5, 2),

  position        integer not null,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),

  constraint topics_code_length check (char_length(code) between 1 and 60),
  constraint topics_name_length check (char_length(name) between 1 and 200),
  constraint topics_position_positive check (position > 0),
  constraint topics_weight_range check (
    blueprint_weight is null or (blueprint_weight >= 0 and blueprint_weight <= 100)
  ),

  -- A topic cannot be its own parent. Combined with the depth trigger below,
  -- this makes cycles impossible.
  constraint topics_no_self_parent check (
    parent_topic_id is null or parent_topic_id <> id
  ),

  constraint topics_course_code_key unique (course_id, code),

  -- FK target for lesson_topics.course_id.
  constraint topics_id_course_key unique (id, course_id)
);

comment on table public.topics is
  'Exam blueprint taxonomy, at most two levels deep. Orthogonal to modules: '
  'a module is how we teach, a topic is how the state tests.';

create index topics_course_position_idx on public.topics (course_id, position);
create index topics_parent_idx on public.topics (parent_topic_id);

create trigger topics_set_updated_at
  before update on public.topics
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- Depth and cycle enforcement.
--
-- The design allows one level of nesting: a topic is either a root or the
-- child of a root. A check constraint cannot express this, because it cannot
-- read another row. A trigger can.
--
-- This is not tidiness for its own sake. A cycle (A parents B, B parents A)
-- makes any recursive walk of the taxonomy loop forever, and the readiness
-- calculation walks the taxonomy. The self-parent check constraint above rules
-- out a one-row cycle; requiring every parent to be a root rules out every
-- longer one, because a cycle of length two or more needs at least one parent
-- that is itself a child.
--
-- SECURITY INVOKER (the default), like every other trigger in this schema. It
-- needs no privileges of its own -- it reads one row of a table the caller can
-- already reach -- and a SECURITY DEFINER trigger here would repeat the Phase 1
-- mistake of rebinding current_user for no reason.
-- ---------------------------------------------------------------------------
create or replace function public.enforce_topic_depth()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  grandparent uuid;
begin
  if new.parent_topic_id is null then
    return new;
  end if;

  select t.parent_topic_id into grandparent
    from public.topics t
   where t.id = new.parent_topic_id;

  if grandparent is not null then
    raise exception
      'topics may nest one level deep; % already has a parent',
      new.parent_topic_id
      using errcode = '23514';
  end if;

  return new;
end;
$$;

comment on function public.enforce_topic_depth() is
  'Restricts the topic tree to two levels and, with topics_no_self_parent, '
  'makes cycles impossible.';

create trigger topics_enforce_depth
  before insert or update of parent_topic_id on public.topics
  for each row execute function public.enforce_topic_depth();

-- ---------------------------------------------------------------------------
-- lesson_topics — which lessons teach which blueprint topics.
--
-- Many-to-many on purpose. One lesson often covers several blueprint topics,
-- and one topic is usually taught across several lessons. This table is what
-- turns "your weakest topic is Texas statutes" into "read these four
-- lessons" -- i.e. what makes a readiness score actionable instead of
-- merely discouraging.
-- ---------------------------------------------------------------------------
create table public.lesson_topics (
  lesson_id uuid not null,
  topic_id  uuid not null,

  -- Carried so that BOTH composite foreign keys below can point at
  -- (id, course_id) pairs. The effect is that a lesson from one course
  -- physically cannot be tagged with a topic from another: there is no
  -- trigger to forget and no application check to bypass, because no such row
  -- satisfies both foreign keys at once.
  course_id uuid not null,

  created_at timestamptz not null default now(),

  constraint lesson_topics_pkey primary key (lesson_id, topic_id),

  constraint lesson_topics_lesson_fkey
    foreign key (lesson_id, course_id)
    references public.lessons (id, course_id)
    on update cascade
    on delete cascade,

  constraint lesson_topics_topic_fkey
    foreign key (topic_id, course_id)
    references public.topics (id, course_id)
    on update cascade
    on delete cascade
);

comment on table public.lesson_topics is
  'Many-to-many between lessons and blueprint topics. The composite foreign '
  'keys make cross-course tagging structurally impossible.';

create index lesson_topics_topic_idx on public.lesson_topics (topic_id);
create index lesson_topics_course_idx on public.lesson_topics (course_id);

-- --------------------------------------------------------------------------
-- 20260201000400_content_grants.sql
-- --------------------------------------------------------------------------

-- ===========================================================================
-- Phase 2 / 05 — Content privileges and the helpers the policies need.
--
-- Supabase's defaults hand `anon` and `authenticated` full privileges on every
-- new table in `public`. Every table below therefore starts with a blanket
-- REVOKE and is then granted narrowly, exactly as Phase 1 does for profiles.
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- public.is_enrolled_in_course(uuid) -> boolean
--
-- SECURITY INVOKER, deliberately.
--
-- The Phase 1 post-mortem was that SECURITY DEFINER had been used reflexively,
-- on a function that did not need it, and that the rebinding it causes made a
-- security trigger a silent no-op. The rule adopted afterwards is that
-- SECURITY DEFINER must be justified, not assumed. It is not justified here:
-- this function reads the caller's OWN enrollment rows, which the caller is
-- already permitted to read under the Phase 1 policy enrollments_select_own.
-- Running it as the owner would add privilege the function has no use for, and
-- would mean a bug in the WHERE clause leaks other students' enrollments
-- instead of returning nothing.
--
-- As an invoker-rights function it is doubly constrained: the WHERE clause
-- filters to auth.uid(), and RLS on enrollments would filter to the same rows
-- even if that clause were deleted.
--
-- Note it is NOT granted to `anon`. Anonymous visitors have no privilege on
-- enrollments at all, so calling it as anon would raise rather than return
-- false -- which is why no anon-facing policy references it.
-- ---------------------------------------------------------------------------
create or replace function public.is_enrolled_in_course(p_course_id uuid)
returns boolean
language sql
stable
set search_path = ''
as $$
  select exists (
    select 1
      from public.enrollments e
     where e.student_id = (select auth.uid())
       and e.course_id = p_course_id
       and e.status = 'active'::public.enrollment_status
       and (e.expires_at is null or e.expires_at > now())
  );
$$;

comment on function public.is_enrolled_in_course(uuid) is
  'True when the current user holds a live (active, unexpired) enrollment in '
  'the given course. SECURITY INVOKER: it reads only the caller''s own rows.';

revoke all on function public.is_enrolled_in_course(uuid) from public;
grant execute on function public.is_enrolled_in_course(uuid)
  to authenticated, service_role;

-- ---------------------------------------------------------------------------
-- public.lesson_is_published(uuid) -> boolean
--
-- A lesson is published only if its module is published and its course is
-- active. Checking the whole chain matters: unpublishing a module must hide
-- its lessons, and archiving a course must hide everything under it, without
-- anyone having to remember to cascade a status change by hand.
--
-- The status tests are written out explicitly rather than inferred from
-- whether the row is visible to the caller. Relying on another table's policy
-- to do the filtering would make this function's meaning depend on a policy in
-- a different migration -- correct today, quietly wrong the first time that
-- policy is edited.
--
-- SECURITY INVOKER again: every table it touches is one the caller may already
-- read, so it needs nothing extra.
-- ---------------------------------------------------------------------------
create or replace function public.lesson_is_published(p_lesson_id uuid)
returns boolean
language sql
stable
set search_path = ''
as $$
  select exists (
    select 1
      from public.lessons l
      join public.modules m on m.id = l.module_id
      join public.courses c on c.id = l.course_id
     where l.id = p_lesson_id
       and l.status = 'active'::public.content_status
       and m.status = 'active'::public.content_status
       and c.status = 'active'::public.course_status
  );
$$;

comment on function public.lesson_is_published(uuid) is
  'True when a lesson, its module and its course are all published.';

revoke all on function public.lesson_is_published(uuid) from public;
grant execute on function public.lesson_is_published(uuid)
  to anon, authenticated, service_role;

-- ---------------------------------------------------------------------------
-- Table privileges.
--
-- The write grants below are inert for ordinary users: there is no non-admin
-- write policy on any of these tables, and RLS can only narrow a privilege,
-- never widen one. They exist because RLS cannot grant what the privilege
-- system has not.
-- ---------------------------------------------------------------------------

revoke all on table public.modules from anon, authenticated;
grant select on table public.modules to anon, authenticated;
grant insert, update, delete on table public.modules to authenticated;

revoke all on table public.lessons from anon, authenticated;
grant select on table public.lessons to anon, authenticated;
grant insert, update, delete on table public.lessons to authenticated;

revoke all on table public.topics from anon, authenticated;
grant select on table public.topics to anon, authenticated;
grant insert, update, delete on table public.topics to authenticated;

revoke all on table public.lesson_topics from anon, authenticated;
grant select on table public.lesson_topics to anon, authenticated;
grant insert, update, delete on table public.lesson_topics to authenticated;

-- lesson_contents is the paid content. `anon` gets NOTHING -- not a
-- restrictive policy, no privilege at all, so an anonymous request to
-- /rest/v1/lesson_contents is refused by the privilege system before RLS is
-- consulted. This is the same belt-and-braces posture the question bank will
-- take in a later migration.
revoke all on table public.lesson_contents from anon, authenticated;
grant select on table public.lesson_contents to authenticated;
grant insert, update, delete on table public.lesson_contents to authenticated;

-- --------------------------------------------------------------------------
-- 20260201000500_content_rls.sql
-- --------------------------------------------------------------------------

-- ===========================================================================
-- Phase 2 / 06 — Row-Level Security for the content tables.
--
-- Same posture as Phase 1: RLS on for every table, and a table with no policy
-- denies everything.
--
-- `(select auth.uid())` stays wrapped in a scalar subquery so Postgres
-- evaluates it once per statement rather than once per row.
-- ===========================================================================

alter table public.modules         enable row level security;
alter table public.lessons         enable row level security;
alter table public.lesson_contents enable row level security;
alter table public.topics          enable row level security;
alter table public.lesson_topics   enable row level security;

-- ---------------------------------------------------------------------------
-- modules — public syllabus
-- ---------------------------------------------------------------------------

-- Published modules of an active course are public. This is marketing copy
-- and structure, not content: a visitor deciding whether to buy needs to see
-- what they would be buying, and a search engine indexing it is the point.
create policy modules_select_published
  on public.modules
  for select
  to anon, authenticated
  using (
    status = 'active'::public.content_status
    and exists (
      select 1
        from public.courses c
       where c.id = modules.course_id
         and c.status = 'active'::public.course_status
    )
  );

create policy modules_select_admin
  on public.modules for select to authenticated
  using (public.is_admin());

create policy modules_insert_admin
  on public.modules for insert to authenticated
  with check (public.is_admin());

create policy modules_update_admin
  on public.modules for update to authenticated
  using (public.is_admin()) with check (public.is_admin());

create policy modules_delete_admin
  on public.modules for delete to authenticated
  using (public.is_admin());

-- ---------------------------------------------------------------------------
-- lessons — public syllabus (titles and structure only; see lesson_contents)
-- ---------------------------------------------------------------------------

-- The whole chain is checked, not just the lesson's own status, so that
-- unpublishing a module hides its lessons and archiving a course hides
-- everything beneath it -- without an author having to cascade the change by
-- hand and without a forgotten row staying visible.
create policy lessons_select_published
  on public.lessons
  for select
  to anon, authenticated
  using (
    status = 'active'::public.content_status
    and exists (
      select 1
        from public.modules m
        join public.courses c on c.id = m.course_id
       where m.id = lessons.module_id
         and m.status = 'active'::public.content_status
         and c.status = 'active'::public.course_status
    )
  );

create policy lessons_select_admin
  on public.lessons for select to authenticated
  using (public.is_admin());

create policy lessons_insert_admin
  on public.lessons for insert to authenticated
  with check (public.is_admin());

create policy lessons_update_admin
  on public.lessons for update to authenticated
  using (public.is_admin()) with check (public.is_admin());

create policy lessons_delete_admin
  on public.lessons for delete to authenticated
  using (public.is_admin());

-- ---------------------------------------------------------------------------
-- lesson_contents — the paid half
-- ---------------------------------------------------------------------------

-- The only non-admin read policy in the content schema that asks who the
-- caller is rather than what the row's status is.
--
-- Both halves are required. Enrollment alone is not enough: a student enrolled
-- in a course must still not read a draft lesson an instructor is midway
-- through writing. Publication alone is obviously not enough: that is the
-- whole product.
--
-- There is deliberately no `to anon` variant. Anonymous visitors hold no
-- privilege on this table at all (see the grants migration), so the request
-- fails before reaching this policy.
create policy lesson_contents_select_enrolled
  on public.lesson_contents
  for select
  to authenticated
  using (
    public.lesson_is_published(lesson_id)
    and public.is_enrolled_in_course(course_id)
  );

create policy lesson_contents_select_admin
  on public.lesson_contents for select to authenticated
  using (public.is_admin());

create policy lesson_contents_insert_admin
  on public.lesson_contents for insert to authenticated
  with check (public.is_admin());

create policy lesson_contents_update_admin
  on public.lesson_contents for update to authenticated
  using (public.is_admin()) with check (public.is_admin());

create policy lesson_contents_delete_admin
  on public.lesson_contents for delete to authenticated
  using (public.is_admin());

-- ---------------------------------------------------------------------------
-- topics — the published exam blueprint
-- ---------------------------------------------------------------------------

-- Public for an active course. The blueprint is a state publication; treating
-- our transcription of it as a secret would protect nothing and would forfeit
-- the most obviously useful page on the site ("what is actually on the Texas
-- exam?"). Topics of a draft course stay hidden, because an unreleased course
-- outline is a business decision rather than a public document.
create policy topics_select_published
  on public.topics
  for select
  to anon, authenticated
  using (
    exists (
      select 1
        from public.courses c
       where c.id = topics.course_id
         and c.status = 'active'::public.course_status
    )
  );

create policy topics_select_admin
  on public.topics for select to authenticated
  using (public.is_admin());

create policy topics_insert_admin
  on public.topics for insert to authenticated
  with check (public.is_admin());

create policy topics_update_admin
  on public.topics for update to authenticated
  using (public.is_admin()) with check (public.is_admin());

create policy topics_delete_admin
  on public.topics for delete to authenticated
  using (public.is_admin());

-- ---------------------------------------------------------------------------
-- lesson_topics — which lessons teach which topics
-- ---------------------------------------------------------------------------

-- Visible whenever the lesson it points at is visible. A tag on a draft lesson
-- would otherwise disclose that the lesson exists, and what it covers, before
-- it is published.
create policy lesson_topics_select_published
  on public.lesson_topics
  for select
  to anon, authenticated
  using (public.lesson_is_published(lesson_id));

create policy lesson_topics_select_admin
  on public.lesson_topics for select to authenticated
  using (public.is_admin());

create policy lesson_topics_insert_admin
  on public.lesson_topics for insert to authenticated
  with check (public.is_admin());

create policy lesson_topics_update_admin
  on public.lesson_topics for update to authenticated
  using (public.is_admin()) with check (public.is_admin());

create policy lesson_topics_delete_admin
  on public.lesson_topics for delete to authenticated
  using (public.is_admin());

-- --------------------------------------------------------------------------
-- 20260201000600_lesson_completions.sql
-- --------------------------------------------------------------------------

-- ===========================================================================
-- Phase 2 / 07 — lesson_completions
--
-- The first row a STUDENT is allowed to write.
--
-- Everything before this is authored by admins; a student's only writes were
-- their own first and last name. This table is different, and it is worth
-- being explicit about why it is safe: marking a lesson read grants nothing.
-- It unlocks no content, confers no entitlement, and changes no price. The
-- worst a dishonest student can do is lie to themselves about their own
-- progress, and a product whose threat model includes "the customer cheats at
-- their own revision" has misunderstood who it is for.
--
-- That is not a reason to skip the checks. The INSERT policy still requires
-- the lesson to be published AND the student to hold a live enrollment,
-- because a completion row for a lesson the student cannot read is not a lie,
-- it is corrupt data: it would count toward a progress percentage whose
-- denominator does not contain it.
-- ===========================================================================

create table public.lesson_completions (
  student_id   uuid not null references public.profiles (id) on delete cascade,
  lesson_id    uuid not null,

  -- Denormalised, and held true by the composite foreign key below, exactly
  -- as on lessons and lesson_contents. The INSERT policy needs a course id to
  -- check enrollment against, and joining to reach one on every row of a
  -- policy evaluation is the cost this column exists to avoid.
  course_id    uuid not null,

  completed_at timestamptz not null default now(),

  -- One row per student per lesson. Re-marking is a no-op rather than a
  -- second row, so "how many lessons has this student finished?" is a count
  -- and never a count of distinct values.
  constraint lesson_completions_pkey primary key (student_id, lesson_id),

  constraint lesson_completions_lesson_fkey
    foreign key (lesson_id, course_id)
    references public.lessons (id, course_id)
    on update cascade
    on delete cascade
);

comment on table public.lesson_completions is
  'A student marking a lesson read. Self-service: students insert and delete '
  'their own rows. Marking a lesson complete grants no access to anything.';

-- Every progress query filters by student and course together.
create index lesson_completions_student_course_idx
  on public.lesson_completions (student_id, course_id);

-- "How many students finished this lesson?" for the later reporting phase.
create index lesson_completions_lesson_idx
  on public.lesson_completions (lesson_id);

-- ---------------------------------------------------------------------------
-- Privileges
-- ---------------------------------------------------------------------------
revoke all on table public.lesson_completions from anon, authenticated;
grant select, insert, delete on table public.lesson_completions to authenticated;
-- No UPDATE, for anyone. A completion has nothing mutable on it: the student
-- id and lesson id are its identity, and `completed_at` is a fact about when
-- something happened. Un-marking is a DELETE, and re-marking inserts a fresh
-- row with a fresh timestamp — which is the honest record of what occurred.
-- No grants at all to `anon`.

-- ---------------------------------------------------------------------------
-- Row-Level Security
-- ---------------------------------------------------------------------------
alter table public.lesson_completions enable row level security;

create policy lesson_completions_select_own
  on public.lesson_completions
  for select
  to authenticated
  using (student_id = (select auth.uid()));

create policy lesson_completions_select_admin
  on public.lesson_completions
  for select
  to authenticated
  using (public.is_admin());

-- The one self-service write in the schema.
--
-- WITH CHECK, not USING: an INSERT has no existing row to test. All three
-- conditions matter:
--   * student_id must be the caller, or one student could fabricate another's
--     progress record.
--   * the lesson must be published, or a student could mark a draft lesson
--     that no progress denominator counts.
--   * the enrollment must be live, or completions accumulate against a course
--     the student cannot read, and a later re-enrollment inherits progress
--     they never made.
create policy lesson_completions_insert_own
  on public.lesson_completions
  for insert
  to authenticated
  with check (
    student_id = (select auth.uid())
    and public.lesson_is_published(lesson_id)
    and public.is_enrolled_in_course(course_id)
  );

-- Un-marking deliberately does NOT require publication or a live enrollment.
-- A student whose access lapsed, or whose lesson was unpublished beneath
-- them, must still be able to clear their own row; the alternative is data
-- they own and cannot remove.
create policy lesson_completions_delete_own
  on public.lesson_completions
  for delete
  to authenticated
  using (student_id = (select auth.uid()));

-- Deliberately absent: any admin INSERT, UPDATE or DELETE policy. Progress is
-- the student's own record of their own study. An admin who could edit it
-- would make every readiness score arguable, and no support request needs it.

-- --------------------------------------------------------------------------
-- 20260201000700_topic_question_count.sql
-- --------------------------------------------------------------------------

-- ===========================================================================
-- Phase 2 / 08 — topics.question_count
--
-- WHY THIS COLUMN EXISTS, having shipped `blueprint_weight` first.
--
-- `blueprint_weight` was added on the assumption that an examination
-- blueprint publishes percentages. The Texas one does not. Pearson VUE
-- publication 124401, "Texas Insurance Content Outlines", assigns each
-- section a NUMBER OF SCOREABLE QUESTIONS:
--
--     I.   TYPES OF POLICIES ............................ 22
--     II.  INSURANCE TERMS AND RELATED CONCEPTS ......... 15
--     ...
--
-- Storing those as percentages would be lossy in both directions. 22 of 130
-- is 16.923…%, so the primary figure cannot be recovered from a
-- numeric(5,2); and a Phase 3 paper generator asked to build a practice exam
-- needs "draw 22 questions from this topic", not a percentage it must
-- multiply and round back into an integer — where the rounding of eight
-- sections can easily miss the exam length by one or two questions.
--
-- So the count is stored as published and the percentage is DERIVED for
-- display. `blueprint_weight` is kept rather than dropped: other states and
-- other lines do publish percentage-weighted blueprints, and this schema is
-- meant to outlive one exam.
--
-- Precedence, applied consistently in the UI: when `question_count` is
-- present it is the authority and any percentage shown is computed from it.
-- `blueprint_weight` is used only when no count exists.
-- ===========================================================================

alter table public.topics
  add column question_count integer;

comment on column public.topics.question_count is
  'Scoreable questions the published blueprint assigns to this topic. The '
  'primary figure where the blueprint gives counts (Texas does). Percentages '
  'shown to users are derived from this, never stored.';

comment on column public.topics.blueprint_weight is
  'Published percentage weighting, for blueprints expressed that way. Ignored '
  'when question_count is set. Texas publishes counts, so this is null there.';

alter table public.topics
  add constraint topics_question_count_positive
  check (question_count is null or question_count between 1 and 500);

commit;
